// The model loader: what it accepts, what it refuses before a single inference
// runs, and what one inference produces.
//
// Every model here is generated by tools/make_test_model.py from the frozen
// deployment fixture, so the valid case is exactly the document the contract
// test parses and every other case differs from it in one way only.
#include "irmv/policy/onnx_model.hpp"

#include <array>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

#include "irmv/protocol/types.hpp"
#include "support/check.hpp"

namespace {

using irmv::policy::DeploymentError;
using irmv::policy::ModelError;
using irmv::policy::Observation;
using irmv::policy::OnnxModel;

// The deployment table the generated fixtures resolve against: exactly the
// three joints of the fixture document, in another order.
const std::vector<std::string> kRobotJoints = {"ankle_pitch", "knee",
                                               "hip_pitch"};

// True when the model is refused, whichever of the two reasons applies: a
// document this build cannot honour is reported as a DeploymentError with the
// field path inside it, a file, session or tensor problem as a ModelError.
bool Refused(const std::string &path) {
  try {
    const std::unique_ptr<OnnxModel> model =
        OnnxModel::Load(path, kRobotJoints);
    (void)model;
  } catch (const DeploymentError &error) {
    return !error.field_path().empty() && !std::string(error.what()).empty();
  } catch (const ModelError &error) {
    return !std::string(error.what()).empty();
  }
  return false;
}

}  // namespace

int main(int argc, char **argv) {
  CHECK(argc == 2);
  const std::string directory = argv[1];
  const auto path = [&directory](const std::string &name) {
    return directory + "/" + name;
  };

  const std::unique_ptr<OnnxModel> model =
      OnnxModel::Load(path("valid.onnx"), kRobotJoints);
  CHECK(model != nullptr);
  // The contract travelled with the file and was validated, and the digest is
  // the one the configured overrides are matched against.
  CHECK(model->contract().schema_version == 1);
  CHECK(model->contract().policy_type == "joint_position");
  CHECK(model->contract().input.name == "obs");
  CHECK(model->contract().input.dimension == 18);
  CHECK(model->contract().output.name == "actions");
  CHECK(model->contract().output.dimension == 3);
  CHECK(model->contract().policy_period_us == 20000);
  CHECK(model->mapping().action == std::vector<std::uint32_t>({1, 2, 0}));
  CHECK(model->mapping().joint_pos == std::vector<std::uint32_t>({0, 1, 2}));
  CHECK(model->mapping().joint_vel == std::vector<std::uint32_t>({2, 0, 1}));
  CHECK(model->sha256().size() == 64);
  CHECK(model->sha256().find_first_not_of("0123456789abcdef") ==
        std::string::npos);

  // One inference on the all-zero observation the contract describes.
  Observation observation;
  observation.count = model->contract().observation.dimension;
  std::array<float, irmv::protocol::kMaxJoints> action{};
  std::uint32_t action_count = 0;
  CHECK(model->Run(observation, &action, &action_count));
  CHECK(action_count == 3);
  for (std::uint32_t index = 0; index < action_count; ++index) {
    CHECK(std::isfinite(action[index]));
  }

  // An observation of the wrong width is refused, never zero-padded.
  Observation short_observation;
  short_observation.count = model->contract().observation.dimension - 1;
  std::uint32_t untouched = 7;
  std::array<float, irmv::protocol::kMaxJoints> refused_action{};
  CHECK(!model->Run(short_observation, &refused_action, &untouched));
  CHECK(untouched == 7);

  // The model file that is not there is an error of the file, not of the
  // contract.
  CHECK(Refused(path("does_not_exist.onnx")));

  // Every way a package can fail to describe itself.
  const char *rejected[] = {
      "no_metadata.onnx",       // no irmv.deployment at all
      "bad_version.onnx",       // schema_version 2
      "io_mismatch.onnx",       // the document declares another input width
      "io_name_mismatch.onnx",  // the document declares another output name
      "dynamic_width.onnx",     // an input width that is not fixed
      "extra_input.onnx",       // two inputs
      "unknown_joint.onnx",     // a joint the deployment does not have
  };
  (void)rejected;
  for (const char *name : rejected) {
    CHECK(Refused(path(name)));
  }

  // A model that carries the contract twice is not tested here: the pinned
  // ONNX Runtime collapses the metadata map before this layer can see it, so
  // the duplicate is caught by the offline gate instead - onnx.checker rejects
  // it, and tools/verify_policy.py runs that checker (see
  // tests/integration/policy_package_test.py). What this layer guarantees is
  // the other half: a model with no contract at all is refused, and the
  // document it does read is validated in full.
  // A model whose output is not finite is a failed policy step, not a frame of
  // infinite targets.
  const std::unique_ptr<OnnxModel> non_finite =
      OnnxModel::Load(path("non_finite.onnx"), kRobotJoints);
  Observation full;
  full.count = non_finite->contract().observation.dimension;
  CHECK(!non_finite->Run(full, &refused_action, &untouched));

  std::cout << "onnx_model_test: ok\n";
  return 0;
}
